inline int xEmoteFind(const char* n) { for (int i = 0; i < XEMOTE_N; i++) if (!strcmp(n, XEMOTES[i].name)) return i; return -1; }
inline const char* xEmoteSound(const char* n) { const int i = xEmoteFind(n); return i >= 0 && XSOUNDS[i][0] ? XSOUNDS[i] : nullptr; }
inline void runXEmote(int idx) {
  const XEmote& e = XEMOTES[idx];
  const char* c = e.name;
  const bool mir = random(100) < 50;                       // left / right swapped
  const float ka = 0.9f + random(21) / 100.0f, kt = 0.9f + random(23) / 100.0f;  // size, tempo
  runStandPose(0);
  if (e.face0) setFaceWithMode(XFACES[e.face0], FACE_ANIM_ONCE);
  for (int i = 0; i < e.n; i++) {
    const XStep& s = XSTEPS[e.first + i];
    if (s.face) setFace(XFACES[s.face]);
    bool any = false;
    EmV4 f = EMV(EMN, EMN, EMN, EMN), b = EMV(EMN, EMN, EMN, EMN);
    for (int l = 0; l < 4; l++) {
      const int src = mir ? (l ^ 1) : l;  // FR<->FL, RR<->RL
      if (s.f[src] != -128) { f.v[l] = s.f[src] * ka; any = true; }
      if (s.b[src] != -128) { b.v[l] = constrain(s.b[src] * ka, -20.0f, 74.0f); any = true; }
    }
    if (any) emoLegsA(max(60, (int)(s.ms * kt)), f, b);
    if (currentCommand != c) return emoFinish(c);
    if (s.pan != -128) {
      const int p = mir ? -s.pan : s.pan;
      if (s.hms) { if (!emoHeadTo(c, p, s.tilt, (int)(s.hms * kt))) return emoFinish(c); }
      else emoHead(p, s.tilt);
    }
    if (s.wait && !emoWait(c, (int)(s.wait * kt))) return emoFinish(c);
  }
  emoFinish(c);
}
